function solve(a, b) {
  const acc = [];
  for (let i = a.length - 1; i >= 0; i--) acc.push(a[i] === '1' ? 1 : 0);
  for (let j = 0; j < b.length; j++) {
    if (b[b.length - 1 - j] !== '1') continue;
    let idx = j;
    while (idx >= acc.length) acc.push(0);
    let carry = 1;
    while (carry > 0) {
      if (idx === acc.length) acc.push(0);
      const total = acc[idx] + carry;
      acc[idx] = total & 1;
      carry = total >> 1;
      idx++;
    }
  }
  while (acc.length > 1 && acc[acc.length - 1] === 0) acc.pop();
  return acc.reverse().join('');
}

function solve(a, b) {
  let i = a.length - 1;
  let j = b.length - 1;
  let carry = 0;
  const out = [];
  while (i >= 0 || j >= 0 || carry > 0) {
    let total = carry;
    if (i >= 0) total += a[i--] === '1' ? 1 : 0;
    if (j >= 0) total += b[j--] === '1' ? 1 : 0;
    out.push(total & 1);
    carry = total >> 1;
  }
  return out.reverse().join('').replace(/^0+(?=[0-9])/, '');
}
